import sys

def find_remaining_marks(n, k, p, x, y, marks):
    current_sum = sum(marks)
    if current_sum > x:
        return [-1]

    remaining_tests = n - k
    min_needed_sum = x - current_sum
    max_possible_sum = remaining_tests * p

    if min_needed_sum > max_possible_sum:
        return [-1]

    target_median_position = (n + 1) // 2

    def check_if_valid(median_value):
        remaining_required_points = 0
        for i in range(target_median_position, len(marks)):
            if marks[i] < median_value:
                remaining_required_points += (median_value - marks[i])

        for i in range(len(marks) - 1, target_median_position - 1, -1):
            if marks[i] >= median_value:
                remaining_required_points -= (marks[i] - median_value)

        return remaining_required_points <= 0

    left, right = 1, p
    while left <= right:
        mid = (left + right) // 2
        if check_if_valid(mid):
            right = mid - 1
        else:
            left = mid + 1

    valid_median = left
    if valid_median == p + 1:
        return [-1]

    remaining_points_needed = 0
    for i in range(target_median_position, len(marks)):
        remaining_points_needed += (valid_median - marks[i])

    remaining_points_available = remaining_tests * p
    if remaining_points_needed > remaining_points_available:
        return [-1]

    result = [valid_median] * remaining_tests
    for i in range(remaining_points_needed):
        result[i] += 1

    return result

